// 英语母语的用户学日语：语法意思、说明和例句译文的英文版（app.js 按句型换上）
// 自动生成：python3 tools/ennat/build.py（编辑 tools/ennat/out/*.json）
const EN_JA_GRAMMAR = {"N5":{"～は":{"m":"topic marker","how":"Noun + は marks the topic of the sentence (what the sentence is about). Pronounced わ (wa).","eg":{"私[は]中国人です。":"I am Chinese.","これ[は]私の傘です。":"This is my umbrella.","今日[は]雨です。":"It's raining today.","田中さん[は]先生です。":"Tanaka is a teacher."}},"～を":{"m":"object marker (the target of an action)","how":"Noun + を + transitive verb. Pronounced お (o).","eg":{"毎朝コーヒー[を]飲みます。":"I drink coffee every morning.","手紙[を]書きます。":"I write a letter.","テレビ[を]見ました。":"I watched TV.","駅で切符[を]買います。":"I buy a ticket at the station."}},"～に（时间）":{"m":"at (a point in time)","how":"Specific time + に. Words like 「今日」 and 「毎日」 do not take に.","eg":{"七時[に]起きます。":"I get up at seven.","日曜日[に]映画を見ます。":"I'm going to see a movie on Sunday.","三月[に]日本へ行きます。":"I'm going to Japan in March.","十時[に]寝ます。":"I go to bed at ten."}},"～に（地点・对象）":{"m":"in, at (location); to (a person); to, onto (destination)","how":"Place where something exists, the target of an action, or the point of arrival + に.","eg":{"机の上[に]本があります。":"There is a book on the desk.","友達[に]手紙を書きます。":"I'm going to write a letter to my friend.","母[に]電話しました。":"I called my mother.","電車[に]乗ります。":"I take the train."}},"～で（场所）":{"m":"at, in (the place where an action happens)","how":"Place + で + action.","eg":{"図書館[で]勉強します。":"I study at the library.","公園[で]遊びます。":"I play in the park.","駅[で]友達を待ちます。":"I wait for my friend at the station.","スーパー[で]野菜を買いました。":"I bought vegetables at the supermarket."}},"～で（手段）":{"m":"with, using; by (means of transport)","how":"Tool, method, means of transport, or language + で.","eg":{"バス[で]学校へ行きます。":"I go to school by bus.","はし[で]ご飯を食べます。":"I eat rice with chopsticks.","日本語[で]話してください。":"Please speak in Japanese.","ペン[で]名前を書きます。":"I write my name with a pen."}},"～へ":{"m":"to, toward (direction)","how":"Place + へ + verb of movement. Pronounced え (e); it can also be replaced with に.","eg":{"来週、京都[へ]行きます。":"I'm going to Kyoto next week.","国[へ]帰ります。":"I'm going back to my home country.","こちら[へ]どうぞ。":"This way, please.","どこ[へ]行きますか。":"Where are you going?"}},"～が":{"m":"subject marker; marks the object of likes, skills, etc.","how":"Noun + が + 好き / 嫌い / 上手 / ある / いる, etc.","eg":{"私は猫[が]好きです。":"I like cats.","庭に犬[が]います。":"There is a dog in the yard.","姉は料理[が]上手です。":"My older sister is good at cooking.","雨[が]降っています。":"It's raining."}},"～も":{"m":"also, too; both, all","how":"Noun + も adds another item of the same kind.","eg":{"私[も]学生です。":"I'm a student too.","妹[も]来ます。":"My younger sister is coming too.","明日[も]雨でしょう。":"It will probably rain tomorrow too.","肉も魚[も]好きです。":"I like both meat and fish."}},"～と":{"m":"and; with","how":"Noun + と + noun / Noun + と一緒に.","eg":{"友達[と]映画を見ました。":"I saw a movie with my friend.","パン[と]牛乳を買いました。":"I bought bread and milk.","家族[と]旅行します。":"I'm going on a trip with my family.","先生[と]話しました。":"I talked with my teacher."}},"～の":{"m":"'s, of","how":"Noun + の + noun shows possession or a characteristic.","eg":{"これは私[の]本です。":"This is my book.","日本語[の]先生です。":"He's a Japanese teacher.","駅の前[の]店です。":"It's the shop in front of the station.","友達[の]家に行きます。":"I'm going to my friend's house."}},"～から～まで":{"m":"from ... to/until ...","how":"Time/place + から + ... + まで.","eg":{"九時[から]五時まで働きます。":"I work from nine to five.","東京から大阪[まで]新幹線で行きます。":"I go from Tokyo to Osaka by shinkansen.","月曜日[から]金曜日まで学校があります。":"I have school from Monday to Friday.","駅[から]家まで歩きます。":"I walk from the station to my house."}},"～か":{"m":"question marker","how":"Adding か to the end of a sentence makes it a question.","eg":{"これは日本語の本です[か]。":"Is this a Japanese book?","明日、学校へ行きます[か]。":"Are you going to school tomorrow?","お名前は何です[か]。":"What is your name?","コーヒーと紅茶、どちらがいいです[か]。":"Which would you like, coffee or tea?"}},"～ね／～よ":{"m":"..., isn't it? (confirming) / ..., you know (informing)","how":"Sentence + ね seeks the listener's agreement; sentence + よ tells the listener something they don't know.","eg":{"今日は暑いです[ね]。":"It's hot today, isn't it?","この料理はおいしいです[よ]。":"This dish is delicious, you know.","あの店は高いです[よ]。":"That shop is expensive, you know.","きれいな花です[ね]。":"That's a beautiful flower, isn't it?"}},"～ませんか":{"m":"won't you ...? / would you like to ...? (invitation)","how":"Verb ます-stem + ませんか.","eg":{"一緒に昼ご飯を食べ[ませんか]。":"Would you like to have lunch together?","週末、映画を見[ませんか]。":"Would you like to see a movie this weekend?","少し休み[ませんか]。":"Would you like to take a little break?","コーヒーを飲み[ませんか]。":"Would you like some coffee?"}},"～ましょう":{"m":"let's ... (suggestion)","how":"Verb ます-stem + ましょう.","eg":{"さあ、始め[ましょう]。":"Well then, let's begin.","一緒に帰り[ましょう]。":"Let's go home together.","駅で会い[ましょう]。":"Let's meet at the station.","少し休み[ましょう]。":"Let's take a little break."}},"～たい":{"m":"want to do","how":"Verb ます-stem + たい (です).","eg":{"日本へ行き[たい]です。":"I want to go to Japan.","冷たい水が飲み[たい]です。":"I want to drink some cold water.","新しい車を買い[たい]です。":"I want to buy a new car.","今日は早く寝[たい]です。":"I want to go to bed early today."}},"～てください":{"m":"please do","how":"Verb て-form + ください.","eg":{"ここに名前を書い[てください]。":"Please write your name here.","ちょっと待っ[てください]。":"Please wait a moment.","窓を開け[てください]。":"Please open the window.","もう一度言っ[てください]。":"Please say it one more time."}},"～てもいいです":{"m":"may, it's all right to (permission)","how":"Verb て-form + もいいです.","eg":{"この部屋を使っ[てもいいです]か。":"May I use this room?","写真を撮っ[てもいいです]か。":"May I take a picture?","もう帰っ[てもいいです]よ。":"You can go home now.","ここに座っ[てもいいです]か。":"May I sit here?"}},"～てはいけません":{"m":"must not","how":"Verb て-form + はいけません.","eg":{"ここでたばこを吸っ[てはいけません]。":"You must not smoke here.","図書館で話し[てはいけません]。":"You must not talk in the library.","この水を飲ん[ではいけません]。":"You must not drink this water.","夜遅く電話し[てはいけません]。":"You must not make phone calls late at night."}},"～ている":{"m":"be doing; be in a state","how":"Verb て-form + いる.","eg":{"今、雨が降っ[ています]。":"It's raining now.","弟は部屋で寝[ています]。":"My younger brother is sleeping in his room.","姉は銀行で働い[ています]。":"My older sister works at a bank.","田中さんは結婚し[ています]。":"Tanaka is married."}},"～より～のほうが":{"m":"B is more ... than A","how":"AよりBのほうが + adjective.","eg":{"犬より猫[のほうが]好きです。":"I like cats more than dogs.","バスより電車[のほうが]速いです。":"Trains are faster than buses.","夏より冬[のほうが]好きです。":"I like winter more than summer.","この本より、あの本[のほうが]おもしろいです。":"That book is more interesting than this one."}},"～から（原因）":{"m":"because, so","how":"Sentence + から gives a (subjective) reason.","eg":{"暑い[から]、窓を開けます。":"It's hot, so I'll open the window.","時間がない[から]、タクシーで行きます。":"I don't have time, so I'll take a taxi.","雨です[から]、家にいます。":"It's raining, so I'm staying home.","おいしい[から]、たくさん食べました。":"It was delicious, so I ate a lot."}},"～ないでください":{"m":"please don't","how":"Verb ない-form + でください.","eg":{"ここに車を止め[ないでください]。":"Please don't park your car here.","写真を撮ら[ないでください]。":"Please don't take pictures.","心配し[ないでください]。":"Please don't worry.","ここで走ら[ないでください]。":"Please don't run here."}},"～が（逆接）":{"m":"but","how":"Sentence + が + sentence expresses a contrast.","eg":{"日本語は難しいです[が]、おもしろいです。":"Japanese is difficult, but it's interesting.","この店は安いです[が]、おいしくないです。":"This restaurant is cheap, but the food isn't good.","行きたいです[が]、時間がありません。":"I'd like to go, but I don't have time.","すみません[が]、駅はどこですか。":"Excuse me, but where is the station?"}},"～たり～たりする":{"m":"do things like A and B; do A, B, and so on","how":"Verb た-form + り lists several actions.","eg":{"休みの日は掃除をし[たり]、洗濯をしたりします。":"On my days off, I do things like cleaning and laundry.","週末は本を読んだり、映画を見[たり]します。":"On weekends, I do things like reading books and watching movies.","昨日は友達と話したり、歌っ[たり]しました。":"Yesterday I did things like chatting and singing with my friends.","公園で走ったり、遊ん[だり]します。":"I do things like running and playing in the park."}},"～前に":{"m":"before","how":"Verb dictionary form / Noun + の + 前に.","eg":{"寝る[前に]歯を磨きます。":"I brush my teeth before going to bed.","食事の[前に]手を洗います。":"I wash my hands before meals.","日本へ来る[前に]、日本語を勉強しました。":"I studied Japanese before coming to Japan.","出かける[前に]、天気を見ます。":"I check the weather before going out."}},"～てから":{"m":"after doing ..., (then)","how":"Verb て-form + から.","eg":{"宿題をし[てから]、遊びます。":"I'll play after I do my homework.","手を洗っ[てから]、ご飯を食べます。":"I wash my hands and then eat.","仕事が終わっ[てから]、買い物に行きます。":"After work is over, I'll go shopping.","シャワーを浴び[てから]寝ます。":"I take a shower and then go to bed."}},"～あとで":{"m":"after","how":"Verb た-form / Noun + の + あとで.","eg":{"授業の[あとで]、図書館へ行きます。":"After class, I'll go to the library.","ご飯を食べた[あとで]、散歩します。":"After eating, I'll take a walk.","仕事の[あとで]、友達に会います。":"After work, I'm going to meet a friend.","映画を見た[あとで]、お茶を飲みました。":"After watching the movie, we had tea."}},"～でしょう":{"m":"probably, I suppose (conjecture)","how":"Plain form (な-adjectives and nouns without だ) + でしょう.","eg":{"明日は雨[でしょう]。":"It will probably rain tomorrow.","あの人は学生[でしょう]。":"That person is probably a student.","試験は難しい[でしょう]。":"The exam will probably be difficult.","もうすぐ着く[でしょう]。":"It'll probably arrive soon."}},"～がほしい":{"m":"want (something)","how":"Noun + がほしい (です).","eg":{"新しいかばん[がほしい]です。":"I want a new bag.","時間[がほしい]です。":"I want time.","何[がほしい]ですか。":"What do you want?","日本人の友達[がほしい]です。":"I want Japanese friends."}},"～に行く（目的）":{"m":"go (somewhere) to do","how":"Verb ます-stem / action noun + に行く.","eg":{"デパートへ服を買い[に行きます]。":"I'm going to the department store to buy clothes.","友達と映画を見[に行きます]。":"I'm going to see a movie with my friend.","京都へ旅行[に行きました]。":"I went on a trip to Kyoto.","駅まで友達を迎え[に行きます]。":"I'm going to the station to pick up my friend."}},"～くなる／～になる":{"m":"become","how":"い-adjective minus い + くなる; な-adjective / noun + になる.","eg":{"冬になって、寒[くなりました]。":"Winter has come, and it has gotten cold.","部屋がきれい[になりました]。":"The room has become clean.","日本語が上手[になりました]。":"My Japanese has gotten better.","姉は医者[になりました]。":"My older sister became a doctor."}},"～だけ":{"m":"only, just","how":"Noun / plain form + だけ.","eg":{"一つ[だけ]ください。":"Just one, please.","私[だけ]知っています。":"Only I know.","少し[だけ]食べました。":"I ate only a little.","見る[だけ]です。":"I'm just looking."}},"もう～ました":{"m":"already (did)","how":"もう + past form of the verb.","eg":{"宿題は[もう]終わりました。":"I've already finished my homework.","[もう]昼ご飯を食べました。":"I've already eaten lunch.","電車は[もう]出ました。":"The train has already left.","[もう]寝ましたか。":"Has he gone to bed already?"}},"まだ～ていません":{"m":"not yet","how":"まだ + verb て-form + いません.","eg":{"レポートは[まだ]書いていません。":"I haven't written the report yet.","[まだ]昼ご飯を食べていません。":"I haven't eaten lunch yet.","兄は[まだ]帰っていません。":"My older brother hasn't come home yet.","その映画は[まだ]見ていません。":"I haven't seen that movie yet."}},"～ではありません":{"m":"is not (negative of nouns and な-adjectives)","how":"Noun / な-adjective + ではありません; in speech you can also say 「じゃありません」. Learners often negate nouns by saying 「～ないです」, which is incorrect.","eg":{"私は学生[ではありません]。":"I'm not a student.","この部屋は静か[ではありません]。":"This room isn't quiet.","あの人は先生[ではありません]。":"That person isn't a teacher.","今日は休み[ではありません]。":"Today isn't a day off."}},"～ませんでした":{"m":"did not (polite past negative)","how":"Verb ます-stem + ませんでした. Expresses something that did not happen in the past; it cannot be replaced by the present negative 「～ません」.","eg":{"昨日は学校へ行き[ませんでした]。":"I didn't go to school yesterday.","今朝は朝ご飯を食べ[ませんでした]。":"I didn't eat breakfast this morning.","先週は雨が降り[ませんでした]。":"It didn't rain last week.","その本は読み[ませんでした]。":"I didn't read that book."}},"～かったです":{"m":"was ... (past tense of い-adjectives)","how":"い-adjective minus い + かったです. A common mistake is saying 「おいしいでした」; 「いい」 becomes 「よかったです」.","eg":{"昨日はとても寒[かったです]。":"It was very cold yesterday.","旅行は楽し[かったです]。":"The trip was fun.","そのケーキはおいし[かったです]。":"That cake was delicious.","試験は難し[かったです]。":"The exam was difficult."}},"～があります／～がいます":{"m":"there is / there are; to be (located)","how":"Place + に + noun + が + あります (inanimate things, plants) / います (people, animals). English uses \"there is / there are\" for both, but Japanese must distinguish between living and non-living things.","eg":{"机の上に本[があります]。":"There is a book on the desk.","公園に子どもたち[がいます]。":"There are children in the park.","駅の前に銀行[があります]。":"There is a bank in front of the station.","庭に猫[がいます]。":"There is a cat in the yard."}},"～や～など":{"m":"A, B, and so on","how":"Noun + や + noun (+ など) gives a few examples and implies there are others; 「と」, by contrast, lists everything.","eg":{"冷蔵庫に牛乳[や]卵などがあります。":"There's milk, eggs, and so on in the fridge.","休みの日は掃除[や]洗濯をします。":"On my days off, I do things like cleaning and laundry.","机の上に本[や]ノートがあります。":"There are books, notebooks, and other things on the desk.","デパートで服[や]靴を買いました。":"I bought clothes, shoes, and so on at the department store."}},"～か～（选择）":{"m":"or","how":"Noun + か + noun means choosing one of them. Be careful not to confuse it with 「か」 at the end of a sentence, which marks a question.","eg":{"コーヒー[か]紅茶をお願いします。":"Coffee or tea, please.","月曜日[か]火曜日に行きます。":"I'll go on Monday or Tuesday.","電車[か]バスで来てください。":"Please come by train or bus.","ペン[か]鉛筆で書いてください。":"Please write with a pen or a pencil."}},"～をください":{"m":"please give me","how":"Noun + をください; a quantity word goes after 「を」 and before 「ください」, as in 「りんごを三つください」.","eg":{"水[をください]。":"Water, please.","このシャツ[をください]。":"I'll take this shirt, please.","コーヒー[をください]。":"Coffee, please.","赤いかばん[をください]。":"I'll take the red bag, please."}},"～ましょうか":{"m":"shall I ...? (offering to help)","how":"Verb ます-stem + ましょうか offers to do something for the listener; it can also be used to suggest something together (\"shall we ...?\").","eg":{"重いですね。荷物を持ち[ましょうか]。":"That's heavy, isn't it? Shall I carry your bags?","暑いですね。窓を開け[ましょうか]。":"It's hot, isn't it? Shall I open the window?","駅まで送り[ましょうか]。":"Shall I take you to the station?","写真を撮り[ましょうか]。":"Shall I take a picture for you?"}},"～くて／～で（形容词连接）":{"m":"both ... and ...; ... and also ... (linking adjectives)","how":"い-adjective minus い + くて; な-adjective / noun + で. Adjectives cannot be linked with 「と」; 「いい」 becomes 「よくて」.","eg":{"この部屋は広[くて]、明るいです。":"This room is spacious and bright.","あの店は安[くて]おいしいです。":"That restaurant is cheap and good.","彼女はきれい[で]、やさしいです。":"She is pretty and kind.","兄は医者[で]、姉は先生です。":"My older brother is a doctor, and my older sister is a teacher."}},"～て、～（动作顺序）":{"m":"... and then ... (sequence of actions)","how":"The verb て-form links several actions in the order they happen; the tense of the whole sentence is determined by the last verb.","eg":{"朝起き[て]、顔を洗います。":"In the morning, I get up and wash my face.","デパートへ行っ[て]、買い物をしました。":"I went to the department store and did some shopping.","家に帰っ[て]、ご飯を食べます。":"I go home and eat dinner.","シャワーを浴び[て]、寝ました。":"I took a shower and went to bed."}},"～とき":{"m":"when, at the time of","how":"Verb plain form / い-adjective / な-adjective + な / noun + の + とき. Nouns must be followed by 「の」 and な-adjectives by 「な」.","eg":{"暇な[とき]、本を読みます。":"When I'm free, I read books.","子どもの[とき]、よく川で遊びました。":"When I was a child, I often played in the river.","寝る[とき]、電気を消します。":"When I go to bed, I turn off the light.","寂しい[とき]、友達に電話します。":"When I'm lonely, I call my friends."}},"～ぐらい／～くらい":{"m":"about, approximately (amount)","how":"Quantity word + ぐらい / くらい expresses an approximate amount or length of time; for an approximate point in time, 「ごろ」 is usually used.","eg":{"駅まで十分[ぐらい]かかります。":"It takes about ten minutes to get to the station.","毎日二時間[ぐらい]勉強します。":"I study for about two hours every day.","パーティーに二十人[くらい]来ました。":"About twenty people came to the party.","このかばんは五千円[ぐらい]です。":"This bag is about 5,000 yen."}},"～ごろ":{"m":"around, about (a point in time)","how":"Point in time + ごろ (に) expresses an approximate point in time; for a length of time, use 「ぐらい」.","eg":{"毎朝七時[ごろ]起きます。":"I get up around seven every morning.","夜十一時[ごろ]寝ます。":"I go to bed around eleven at night.","三時[ごろ]友達が来ます。":"My friend is coming around three.","来月の十日[ごろ]国へ帰ります。":"I'm going back to my home country around the tenth of next month."}},"～の中で～がいちばん":{"m":"the most ... among ...","how":"Noun for the group + の中で + noun / question word + が + いちばん + adjective. To ask a question, use 「何 / だれ / どこ + が いちばん」.","eg":{"果物の中でりんごが[いちばん]好きです。":"Of all fruits, I like apples the best.","クラスの中で山本さんが[いちばん]背が高いです。":"Yamamoto is the tallest in the class.","一年の中で八月が[いちばん]暑いです。":"August is the hottest month of the year.","スポーツの中で何が[いちばん]好きですか。":"Of all sports, which do you like the best?"}},"あまり～ない":{"m":"not very, not much","how":"あまり + negative form (ない / ません). It must be used with a negative; you cannot say 「あまり好きです」.","eg":{"この映画は[あまり]面白くないです。":"This movie isn't very interesting.","私は[あまり]テレビを見ません。":"I don't watch TV much.","今日は[あまり]寒くないです。":"It's not very cold today.","肉は[あまり]食べません。":"I don't eat much meat."}},"ぜんぜん～ない":{"m":"not at all; not in the least","how":"ぜんぜん (全然) + negative form; much stronger than 「あまり～ない」.","eg":{"日本語が[ぜんぜん]わかりません。":"I don't understand Japanese at all.","昨日は[ぜんぜん]寝ませんでした。":"I didn't sleep at all yesterday.","この料理は[ぜんぜん]辛くないです。":"This dish isn't spicy at all.","お酒は[ぜんぜん]飲みません。":"I don't drink alcohol at all."}},"～はどうですか":{"m":"how is ...? / how about ...?","how":"Noun + はどうですか is used to ask for someone's impressions or to make a suggestion; a more polite way to say it is 「～はいかがですか」.","eg":{"日本の生活[はどうですか]。":"How is life in Japan?","明日[はどうですか]。":"How about tomorrow?","このシャツ[はどうですか]。":"How about this shirt?","お茶[はどうですか]。":"How about some tea?"}},"～く／～に（修饰动词）":{"m":"-ly (adjectives used as adverbs)","how":"い-adjective minus い + く; な-adjective + に; used to modify verbs. The basic form of an adjective cannot modify a verb directly.","eg":{"明日は早[く]起きてください。":"Please get up early tomorrow.","図書館では静か[に]してください。":"Please be quiet in the library.","字を大き[く]書きます。":"I write the letters big.","部屋をきれい[に]掃除しました。":"I cleaned the room until it was spotless."}},"～に～回（频率）":{"m":"... times per (period) (frequency)","how":"Period (一日, 一週間, etc.) + に + number of times (～回) expresses frequency.","eg":{"一週間[に]三回プールへ行きます。":"I go to the pool three times a week.","一日[に]二回歯を磨きます。":"I brush my teeth twice a day.","一か月[に]一回映画を見ます。":"I see a movie once a month.","一年[に]二回国へ帰ります。":"I go back to my home country twice a year."}}},"N4":{"～たことがある":{"m":"have done (before) (experience)","how":"Verb た-form + ことがある.","eg":{"富士山に登っ[たことがあります]。":"I have climbed Mt. Fuji.","すしを食べ[たことがあります]か。":"Have you ever eaten sushi?","一度も飛行機に乗っ[たことがありません]。":"I have never been on a plane, not even once.","この本は前に読ん[だことがあります]。":"I've read this book before."}},"～つもりだ":{"m":"intend to, plan to","how":"Verb dictionary form / ない-form + つもりだ.","eg":{"来年、日本に留学する[つもりです]。":"I plan to study abroad in Japan next year.","今日はどこへも行かない[つもりです]。":"I don't plan to go anywhere today.","夏休みに車の免許を取る[つもりです]。":"I plan to get my driver's license during summer vacation.","彼女と結婚する[つもりです]。":"I intend to marry her."}},"～ようと思う":{"m":"think I'll ..., intend to (volition)","how":"Verb volitional form + と思う.","eg":{"週末は家でゆっくりし[ようと思います]。":"I think I'll take it easy at home this weekend.","来年から料理を習[おうと思います]。":"I'm thinking of taking cooking lessons starting next year.","今晩は早く寝[ようと思います]。":"I think I'll go to bed early tonight.","新しいパソコンを買[おうと思っています]。":"I'm thinking of buying a new computer."}},"～なければならない":{"m":"must, have to","how":"Verb ない-form with ない removed + なければならない.","eg":{"明日までにレポートを出さ[なければなりません]。":"I have to submit the report by tomorrow.","薬を飲ま[なければなりません]。":"I have to take my medicine.","毎日漢字を練習し[なければなりません]。":"I have to practice kanji every day.","もう帰ら[なければなりません]。":"I have to go home now."}},"～なくてもいい":{"m":"don't have to; it's all right not to","how":"Verb ない-form with the final い removed + くてもいい.","eg":{"明日は来[なくてもいいです]。":"You don't have to come tomorrow.","全部食べ[なくてもいいです]よ。":"You don't have to eat it all.","急が[なくてもいいです]。":"You don't have to hurry.","靴を脱が[なくてもいいです]。":"You don't have to take off your shoes."}},"～ながら":{"m":"while (doing two things at once)","how":"Verb ます-stem + ながら.","eg":{"音楽を聞き[ながら]勉強します。":"I study while listening to music.","テレビを見[ながら]ご飯を食べます。":"I eat while watching TV.","歩き[ながら]電話しないでください。":"Please don't talk on the phone while walking.","働き[ながら]大学に通っています。":"I'm going to college while working."}},"～たら":{"m":"if; when, after","how":"Verb た-form + ら.","eg":{"駅に着い[たら]、電話してください。":"Please call me when you get to the station.","雨が降っ[たら]、行きません。":"If it rains, I won't go.","お金があっ[たら]、旅行したいです。":"If I had money, I'd like to travel.","家に帰っ[たら]、すぐ寝ます。":"When I get home, I'll go straight to bed."}},"～ば":{"m":"if ..., (then)","how":"Verb conditional form (e-row sound) + ば; い-adjective minus い + ければ.","eg":{"この薬を飲め[ば]、すぐ治りますよ。":"If you take this medicine, you'll get better right away.","安けれ[ば]、買います。":"If it's cheap, I'll buy it.","急げ[ば]、間に合います。":"If you hurry, you'll make it in time.","練習すれ[ば]、上手になります。":"If you practice, you'll get better."}},"～と（条件）":{"m":"when(ever), as soon as (natural result)","how":"Verb dictionary form + と expresses an inevitable result.","eg":{"このボタンを押す[と]、ドアが開きます。":"When you press this button, the door opens.","春になる[と]、桜が咲きます。":"When spring comes, the cherry blossoms bloom.","まっすぐ行く[と]、駅があります。":"If you go straight, you'll find the station.","お酒を飲む[と]、顔が赤くなります。":"When I drink alcohol, my face turns red."}},"～ので":{"m":"because, so (objective reason)","how":"Plain form + ので (な-adjective / noun + なので).","eg":{"雨が降っている[ので]、出かけません。":"It's raining, so I'm not going out.","頭が痛い[ので]、早く帰ります。":"I have a headache, so I'm going home early.","明日は休みな[ので]、ゆっくり寝ます。":"Tomorrow is a day off, so I'll sleep in.","道が込んでいた[ので]、遅れました。":"The roads were crowded, so I was late."}},"～のに":{"m":"even though ..., (yet)","how":"Plain form + のに expresses dissatisfaction or surprise.","eg":{"たくさん勉強した[のに]、試験に落ちました。":"Even though I studied hard, I failed the exam.","約束した[のに]、彼は来ませんでした。":"Even though he promised, he didn't come.","日曜日な[のに]、仕事があります。":"Even though it's Sunday, I have to work.","高い[のに]、おいしくないです。":"It's expensive, and yet it doesn't taste good."}},"～そうだ（样态）":{"m":"looks, seems (appearance)","how":"Verb ます-stem / adjective stem + そうだ.","eg":{"このケーキはおいし[そうです]ね。":"This cake looks delicious.","雨が降り[そうです]。":"It looks like it's going to rain.","彼はとても元気[そうです]。":"He looks very well.","この箱は重[そうです]ね。":"This box looks heavy."}},"～そうだ（传闻）":{"m":"I hear that (hearsay)","how":"Plain form + そうだ.","eg":{"天気予報によると、明日は雨だ[そうです]。":"According to the weather forecast, it's going to rain tomorrow.","田中さんは来月結婚する[そうです]。":"I hear Tanaka is getting married next month.","あの店のラーメンはおいしい[そうです]。":"I hear the ramen at that restaurant is good.","山田さんは病気だ[そうです]。":"I hear Yamada is sick."}},"～てしまう":{"m":"finish doing; do accidentally / regrettably","how":"Verb て-form + しまう.","eg":{"財布をなくし[てしまいました]。":"I went and lost my wallet.","宿題を全部やっ[てしまいました]。":"I finished all my homework.","電車に傘を忘れ[てしまいました]。":"I left my umbrella on the train.","ケーキを一人で食べ[てしまいました]。":"I ate the whole cake by myself."}},"～ておく":{"m":"do in advance","how":"Verb て-form + おく.","eg":{"旅行の前にホテルを予約し[ておきます]。":"I'll book a hotel before the trip.","会議の前に資料を読ん[でおきます]。":"I'll read the materials before the meeting.","ビールを冷やし[ておきました]。":"I chilled the beer ahead of time.","窓を開け[ておいてください]。":"Please leave the window open."}},"～てみる":{"m":"try doing","how":"Verb て-form + みる.","eg":{"この服を着[てみても]いいですか。":"May I try on these clothes?","日本の料理を作っ[てみました]。":"I tried making Japanese food.","一度食べ[てみてください]。":"Please try it once.","先生に聞い[てみます]。":"I'll try asking the teacher."}},"～てあげる／～てくれる／～てもらう":{"m":"do for someone / someone does for me / have someone do for me","how":"Verb て-form + あげる / くれる / もらう.","eg":{"妹に本を読ん[であげました]。":"I read a book to my younger sister.","友達が駅まで送っ[てくれました]。":"My friend took me to the station.","先生に作文を直し[てもらいました]。":"I had my teacher correct my essay.","母がセーターを編ん[でくれました]。":"My mother knitted a sweater for me."}},"～やすい":{"m":"easy to","how":"Verb ます-stem + やすい.","eg":{"このペンは書き[やすい]です。":"This pen is easy to write with.","この本は字が大きくて読み[やすい]です。":"This book has large print and is easy to read.","冬は風邪をひき[やすい]です。":"It's easy to catch a cold in winter.","先生の説明はわかり[やすい]です。":"The teacher's explanations are easy to understand."}},"～にくい":{"m":"hard to","how":"Verb ます-stem + にくい.","eg":{"この漢字は覚え[にくい]です。":"This kanji is hard to remember.","この靴は歩き[にくい]です。":"These shoes are hard to walk in.","彼の字は読み[にくい]です。":"His handwriting is hard to read.","この薬は苦くて飲み[にくい]です。":"This medicine is bitter and hard to swallow."}},"～させる（使役）":{"m":"make / let (someone) do (causative)","how":"Verb causative form.","eg":{"母は弟に野菜を食べ[させました]。":"My mother made my younger brother eat his vegetables.","先生は学生に作文を書か[せました]。":"The teacher had the students write essays.","子供を公園で遊ば[せます]。":"I let the children play in the park.","部長は私を出張に行か[せました]。":"My department manager made me go on a business trip."}},"～られる（被动）":{"m":"be done (passive)","how":"Verb passive form.","eg":{"先生に褒め[られました]。":"I was praised by my teacher.","電車で足を踏ま[れました]。":"Someone stepped on my foot on the train.","雨に降ら[れて]、ぬれてしまいました。":"I got caught in the rain and got wet.","この寺は八百年前に建て[られました]。":"This temple was built 800 years ago."}},"～ことができる":{"m":"can, be able to","how":"Verb dictionary form + ことができる.","eg":{"私は泳ぐ[ことができます]。":"I can swim.","ここで写真を撮る[ことができます]か。":"Can I take pictures here?","漢字を書く[ことができません]。":"I can't write kanji.","このカードで買い物する[ことができます]。":"You can shop with this card."}},"～ほうがいい":{"m":"had better, it's best to","how":"Verb た-form / ない-form + ほうがいい.","eg":{"早く寝た[ほうがいいです]よ。":"You'd better go to bed early.","無理しない[ほうがいいです]。":"You'd better not push yourself too hard.","病院へ行った[ほうがいいです]。":"You should go to the hospital.","傘を持って行った[ほうがいいです]。":"You'd better take an umbrella with you."}},"～ように言う":{"m":"tell (someone) to do","how":"Verb dictionary form / ない-form + ように言う.","eg":{"先生に早く来る[ように言われました]。":"My teacher told me to come early.","弟に部屋を片付ける[ように言いました]。":"I told my younger brother to clean up his room.","医者にお酒を飲まない[ように言われました]。":"The doctor told me not to drink alcohol.","母に野菜を食べる[ように言われます]。":"My mother tells me to eat vegetables."}},"～ようになる":{"m":"become able to; come to (do)","how":"Verb dictionary form / potential form + ようになる.","eg":{"日本語が話せる[ようになりました]。":"I've become able to speak Japanese.","朝早く起きる[ようになりました]。":"I've started getting up early in the morning.","自転車に乗れる[ようになりました]。":"I've learned to ride a bicycle.","漢字が読める[ようになりました]。":"I can read kanji now."}},"～かもしれない":{"m":"might, may","how":"Plain form (な-adjectives and nouns without だ) + かもしれない.","eg":{"明日は雨[かもしれません]。":"It might rain tomorrow.","彼はもう帰った[かもしれません]。":"He may have already gone home.","その話は本当[かもしれません]。":"That story might be true.","少し遅れる[かもしれません]。":"I might be a little late."}},"～はずだ":{"m":"should (be), is expected to","how":"Plain form + はずだ.","eg":{"彼はもう着いた[はずです]。":"He should have arrived by now.","今日は休みの[はずです]。":"Today should be a day off.","この道で合っている[はずです]。":"This should be the right way.","田中さんも来る[はずです]。":"Tanaka should be coming too."}},"～し":{"m":"and, what's more (listing reasons)","how":"Plain form + し lists reasons.","eg":{"この店は安い[し]、おいしいです。":"This restaurant is cheap, and the food is good too.","雨も降っている[し]、今日は家にいます。":"It's raining, too, so I'll stay home today.","彼は親切だ[し]、おもしろいです。":"He's kind, and he's funny too.","時間もない[し]、お金もありません。":"I have no time, and I have no money either."}},"～しか～ない":{"m":"only, nothing but (emphasizing how little)","how":"Noun + しか + negative.","eg":{"財布に千円[しか]ありません。":"I only have 1,000 yen in my wallet.","日本語は少し[しか]話せません。":"I can only speak a little Japanese.","朝はコーヒー[しか]飲みません。":"I only drink coffee in the morning.","この店は日曜日[しか]開いていません。":"This shop is only open on Sundays."}},"～間に":{"m":"while, during (something happens at some point within a period)","how":"Verb dictionary form / ている form / Noun + の + 間に.","eg":{"子供が寝ている[間に]、掃除をします。":"I'll clean while the children are asleep.","留守の[間に]、友達が来ました。":"A friend came by while I was out.","日本にいる[間に]、富士山に登りたいです。":"I want to climb Mt. Fuji while I'm in Japan.","夏休みの[間に]、運転免許を取りました。":"I got my driver's license during summer vacation."}},"～すぎる":{"m":"too, excessively","how":"Verb ます-stem / adjective stem + すぎる.","eg":{"食べ[すぎて]、おなかが痛いです。":"I ate too much, and now my stomach hurts.","この問題は難し[すぎます]。":"This problem is too difficult.","昨日はお酒を飲み[すぎました]。":"I drank too much yesterday.","この部屋は静か[すぎます]。":"This room is too quiet."}},"～ために（目的）":{"m":"in order to; for (the sake of)","how":"Verb dictionary form / Noun + の + ために.","eg":{"日本へ留学する[ために]、貯金しています。":"I'm saving money to study abroad in Japan.","健康の[ために]、毎日歩きます。":"I walk every day for my health.","家族の[ために]働いています。":"I work for my family.","試験に合格する[ために]、頑張ります。":"I'll do my best to pass the exam."}},"～かどうか":{"m":"whether or not","how":"Plain form (な-adjectives and nouns without だ) + かどうか.","eg":{"明日晴れる[かどうか]わかりません。":"I don't know whether it will be sunny tomorrow.","彼が来る[かどうか]聞いてください。":"Please ask him whether he's coming.","この答えが正しい[かどうか]調べます。":"I'll check whether this answer is correct.","おいしい[かどうか]、食べてみます。":"I'll taste it to see whether it's good."}},"～てある":{"m":"(something) has been done (on purpose) and remains that way","how":"Transitive verb て-form + ある, often in the pattern 「～が～てある」, shows that the result of an action someone did on purpose still remains. Note: intransitive verbs cannot take てある (wrong: ドアが開いてある; right: ドアが開いている / ドアが開けてある).","eg":{"窓が開け[てあります]。":"The window has been left open.","壁に地図が貼っ[てあります]。":"A map has been put up on the wall.","ビールはもう冷蔵庫に入れ[てあります]。":"The beer has already been put in the fridge.","ホテルはもう予約し[てあります]。":"The hotel has already been booked."}},"～ていく／～てくる":{"m":"go / come (after doing); go on ... / come to ... (over time)","how":"Verb て-form + いく / くる. (1) Space: go or come after doing something (take an umbrella with you, buy something and bring it back). (2) Time: くる shows a change continuing from the past up to now; いく shows something continuing from now into the future. Note that the て-form is required (wrong: 持つ行く; right: 持っていく).","eg":{"傘を持っ[ていきます]。":"I'll take an umbrella with me.","だんだん寒くなっ[てきました]。":"It has gradually gotten colder.","これからも日本語を勉強し[ていきます]。":"I'll keep on studying Japanese from now on.","駅でパンを買っ[てきました]。":"I bought some bread at the station and brought it back."}},"～がする":{"m":"there is a (sound, smell, taste, etc.); to sense","how":"Noun (音, 声, におい, 味, 気, etc.) + がする. Expresses something the senses perceive naturally. Where English says \"I smell something nice\" or \"I hear a sound\", Japanese does not use 「を聞く」 or 「を嗅ぐ」 but says 「においがする」 or 「音がする」.","eg":{"台所からいいにおい[がします]。":"There's a nice smell coming from the kitchen.","隣の部屋から変な音[がしました]。":"There was a strange noise from the next room.","このお茶は甘い味[がします]。":"This tea tastes sweet.","外で子どもの声[がします]。":"I can hear children's voices outside."}},"～なさい":{"m":"do ...! (command)","how":"Verb ます-stem + なさい. A gentle command from someone above to someone below, such as a parent to a child or a teacher to a student; it is also common in test instructions (「答えなさい」). It cannot be used toward elders or superiors.","eg":{"早く寝[なさい]。":"Go to bed now!","ご飯の前に手を洗い[なさい]。":"Wash your hands before eating.","次の質問に答え[なさい]。":"Answer the following questions.","ちゃんと野菜も食べ[なさい]。":"Eat your vegetables properly, too."}},"～方":{"m":"way of doing, how to","how":"Verb ます-stem + 方 (かた); the whole phrase becomes a noun. Note that the object particle 「を」 changes to 「の」 (wrong: 漢字を書き方; right: 漢字の書き方).","eg":{"この漢字の読み[方]を教えてください。":"Please tell me how to read this kanji.","駅への行き[方]がわかりません。":"I don't know how to get to the station.","このカメラの使い[方]は簡単です。":"This camera is easy to use.","おいしいカレーの作り[方]を習いました。":"I learned how to make delicious curry."}},"～始める":{"m":"begin to, start doing","how":"Verb ます-stem + 始める. Expresses the start of an action or change; it can also be used for planned actions. Compare: 「～出す」 emphasizes a sudden, involuntary start.","eg":{"去年からピアノを習い[始めました]。":"I started taking piano lessons last year.","昨日からこの本を読み[始めました]。":"I started reading this book yesterday.","桜が咲き[始めました]。":"The cherry blossoms have started to bloom.","みんなが食べ[始めて]から、私も食べました。":"After everyone started eating, I ate too."}},"～終わる":{"m":"finish doing","how":"Verb ます-stem + 終わる. Expresses that an action is finished, like English \"finish writing\", \"finish eating\", \"finish reading\". Note that 終わる cannot simply be put after a verb in its dictionary form; it attaches to the ます-stem (書き終わる, not 書く終わる).","eg":{"レポートを書き[終わりました]。":"I finished writing the report.","この本を読み[終わったら]、貸してください。":"When you finish reading this book, please lend it to me.","ご飯を食べ[終わって]から、テレビを見ます。":"After I finish eating, I'll watch TV.","宿題をやり[終わった]人は帰ってもいいです。":"Those who have finished their homework may go home."}},"～出す":{"m":"suddenly start to","how":"Verb ます-stem + 出す. Expresses that an action starts suddenly, mostly for things beyond one's control (crying, laughing, rain, running, etc.). It cannot be used for planned actions (wrong: 明日から勉強し出します; right: 勉強し始めます).","eg":{"赤ちゃんが急に泣き[出しました]。":"The baby suddenly started crying.","話を聞いて、みんな笑い[出しました]。":"Hearing the story, everyone burst out laughing.","急に雨が降り[出しました]。":"It suddenly started to rain.","犬が突然走り[出しました]。":"The dog suddenly started running."}},"～がる":{"m":"(someone else) feels, wants","how":"い-adjective minus い / な-adjective stem + がる; ～たい becomes ～たがる; 欲しい becomes 欲しがる. Used to describe a third person's feelings or wishes. A common mistake: when talking about someone else, you cannot simply say 「彼は寒い」 or 「彼は行きたい」 the way English says \"he is cold\" or \"he wants to go\"; say 「寒がっている」 or 「行きたがっている」.","eg":{"妹は暗い所を怖[がります]。":"My younger sister is afraid of the dark.","子どもが外で遊びた[がっています]。":"The children want to play outside.","弟は新しいゲームを欲し[がっています]。":"My younger brother wants the new game.","母はその知らせを聞いて、とても残念[がりました]。":"When my mother heard the news, she was very disappointed."}},"～までに":{"m":"by (a deadline)","how":"Noun / verb dictionary form + までに. Shows the deadline by which a one-time action is completed. Difference from 「まで」: まで means an action continues up until a certain time (wrong: 5時までに待つ; right: 5時まで待つ).","eg":{"金曜日[までに]レポートを出してください。":"Please submit the report by Friday.","9時[までに]会社に来てください。":"Please come to the office by 9.","暗くなる[までに]家に帰りましょう。":"Let's go home before it gets dark.","来週[までに]この本を返します。":"I'll return this book by next week."}},"～ないで":{"m":"without doing; instead of doing","how":"Verb ない-form + で. Means doing the second action without doing the first (accompanying state), or doing the second action instead of the first (substitution). Unlike 「～なくて」, 「～ないで」 does not express a cause.","eg":{"朝ご飯を食べ[ないで]学校へ行きました。":"I went to school without eating breakfast.","傘を持た[ないで]出かけました。":"I went out without taking an umbrella.","昨夜は寝[ないで]勉強しました。":"Last night I stayed up studying without sleeping.","バスに乗ら[ないで]歩いて帰りました。":"I walked home instead of taking the bus."}},"～なくて（原因）":{"m":"because (something) doesn't / didn't happen","how":"Verb ない-form with ない changed to なくて; い-adjective minus い + くなくて; noun / な-adjective + じゃなくて. Expresses a cause; the second part is usually a feeling or an uncontrollable result, and cannot be a command, request, or statement of intention.","eg":{"宿題が終わら[なくて]、困っています。":"I can't finish my homework, and I don't know what to do.","試験に合格でき[なくて]、残念でした。":"I was disappointed that I couldn't pass the exam.","バスが来[なくて]、遅刻しました。":"The bus didn't come, so I was late.","友達から連絡が[なくて]、心配しています。":"I haven't heard from my friend, so I'm worried."}},"～て／～くて（原因）":{"m":"because ..., (so)","how":"Verb て-form; い-adjective minus い + くて; な-adjective / noun + で. Expresses a cause; the second part is usually a feeling, state, or ability (うれしい, 困る, できない, etc.). It cannot be followed by an expression of intention, a command, or a request (wrong: 暑くて窓を開けてください; right: 暑いから窓を開けてください).","eg":{"ニュースを聞い[て]、びっくりしました。":"I was surprised to hear the news.","この問題は難し[くて]、わかりません。":"This problem is so difficult that I can't do it.","かばんが重[くて]、持てません。":"The bag is so heavy that I can't carry it.","久しぶりに友達に会え[て]、うれしかったです。":"I was happy to see my friend for the first time in a long time."}},"～てもかまわない":{"m":"it's all right if, I don't mind if","how":"Verb て-form / い-adjective くて / な-adjective or noun + で + もかまわない. Same meaning as 「～てもいい」 but slightly more formal; the negative 「～なくてもかまわない」 means there is no need to.","eg":{"ここで写真を撮っ[てもかまいません]。":"It's all right to take pictures here.","明日は来なく[てもかまいません]。":"It's all right if you don't come tomorrow.","少し高く[てもかまいません]。":"I don't mind if it's a little expensive.","ボールペンで書い[てもかまいませんか]。":"Is it all right if I write with a ballpoint pen?"}},"～ずつ":{"m":"each; ... at a time","how":"Quantity word + ずつ. Expresses equal distribution, or repeating something in the same amount. Note that it attaches to quantity words, not ordinary nouns (wrong: 人ずつ; right: 一人ずつ).","eg":{"りんごを一人二つ[ずつ]取ってください。":"Please take two apples each.","毎日少し[ずつ]日本語を勉強しています。":"I study Japanese a little at a time every day.","一人[ずつ]部屋に入ってください。":"Please enter the room one at a time.","薬は一回に三錠[ずつ]飲んでください。":"Take three tablets of this medicine each time."}},"～なら":{"m":"if (giving advice on a topic the listener raised)","how":"Verb / い-adjective plain form, noun / な-adjective stem + なら. Picks up a topic the other person mentioned and gives advice or a judgment. Unlike 「たら」, with なら the second part can happen before the first (「行くなら地図を買っておこう」).","eg":{"日本へ行く[なら]、夏より秋がいいですよ。":"If you're going to Japan, autumn is better than summer.","パソコンを買う[なら]、この店が安いです。":"If you're going to buy a computer, this shop is cheap.","すし[なら]、駅前の店がおいしいです。":"If it's sushi you want, the place in front of the station is good.","疲れている[なら]、早く休んだほうがいいです。":"If you're tired, you should get some rest early."}},"～たらどうですか":{"m":"why don't you ...? (suggestion)","how":"Verb た-form + らどうですか (in casual speech, just 「～たら?」). Used to make a suggestion to the listener. For elders or superiors, the more polite 「～たらいかがですか」 is better.","eg":{"疲れているなら、少し休ん[だらどうですか]。":"If you're tired, why don't you rest a bit?","わからないなら、先生に聞い[たらどうですか]。":"If you don't understand, why don't you ask the teacher?","熱があるなら、病院へ行っ[たらどうですか]。":"If you have a fever, why don't you go to the hospital?","もう遅いから、タクシーで帰っ[たらどうですか]。":"It's already late, so why don't you take a taxi home?"}},"～ばいい":{"m":"all you have to do is; what should I do","how":"Verb ば-form + いい. Expresses a way to achieve a goal, or advice; the question 「どうすればいいですか」 is used to ask what one should do. 「～たらいい」 can also be used.","eg":{"駅までどう行け[ばいいですか]。":"How should I get to the station?","わからないときは、辞書で調べれ[ばいいです]。":"When you don't understand something, you can just look it up in a dictionary.","このボタンを押せ[ばいいです]。":"All you have to do is press this button.","何を持っていけ[ばいいですか]。":"What should I bring?"}},"～ていただけませんか":{"m":"could you please ...? (polite request)","how":"Verb て-form + いただけませんか. A more polite request than 「～てください」 or 「～てくれませんか」, used toward superiors and strangers. A slightly more casual version is 「～てもらえませんか」.","eg":{"すみません、写真を撮っ[ていただけませんか]。":"Excuse me, could you take a picture for me?","もう少しゆっくり話し[ていただけませんか]。":"Could you please speak a little more slowly?","この漢字の読み方を教え[ていただけませんか]。":"Could you tell me how to read this kanji?","ここに住所を書い[ていただけませんか]。":"Could you please write your address here?"}},"お～になる":{"m":"(honorific) someone respected does","how":"お + verb ます-stem + になる (Sino-Japanese words usually use 「ご～になる」). Elevates the actions of the listener or a superior. Note: する, 来る, 見る, いる, etc. have special honorific verbs and do not use this form; it also cannot be used for your own actions.","eg":{"社長はもうお帰り[になりました]。":"The company president has already gone home.","先生は何時ごろお戻り[になりますか]。":"Around what time will the teacher be back?","このペンをお使い[になりますか]。":"Would you like to use this pen?","お客様はもうお休み[になりました]。":"The guest has already gone to bed."}},"お～する":{"m":"(humble) I do (for you)","how":"お + verb ます-stem + する (Sino-Japanese words use 「ご～する」, as in ご案内する). Shows respect by lowering your own side's action; used only for actions that involve the other person (wrong: お食べする).","eg":{"荷物をお持ち[します]。":"I'll carry your bags for you.","駅までお送り[しましょうか]。":"Shall I take you to the station?","後でお電話[します]。":"I'll call you later.","先生に本をお借り[しました]。":"I borrowed a book from my teacher."}},"～という":{"m":"called, named","how":"Noun + という + noun. Used to introduce a name the listener may not know (a person's name, a place name, a shop name, etc.). In casual speech, 「～って」 is often used.","eg":{"これは「すきやき」[という]料理です。":"This is a dish called \"sukiyaki.\"","山田さん[という]人から電話がありました。":"You had a call from someone named Yamada.","「さくら」[という]店で昼ご飯を食べました。":"I had lunch at a restaurant called \"Sakura.\"","これは何[という]花ですか。":"What is this flower called?"}},"～と思う":{"m":"I think (that)","how":"Plain form + と思う; nouns and な-adjectives need だ (静かだと思う). Expresses the speaker's guess or opinion. Learners often leave out the だ (wrong: 静かと思います); to report what a third person thinks, use 「～と思っている」.","eg":{"明日は雨が降る[と思います]。":"I think it will rain tomorrow.","この映画はおもしろい[と思います]。":"I think this movie is interesting.","田中さんはもう帰った[と思います]。":"I think Tanaka has already gone home.","この町は静かだ[と思います]。":"I think this town is quiet."}},"～ことがある（有时）":{"m":"sometimes (do)","how":"Verb dictionary form / ない-form + ことがある. Expresses something that happens occasionally. Be careful to distinguish it from 「～たことがある」 (experience): with the dictionary form it means \"sometimes\"; with the た-form it means \"have done before\".","eg":{"朝ご飯を食べない[ことがあります]。":"Sometimes I don't eat breakfast.","忙しいときは、夜遅くまで働く[ことがあります]。":"When I'm busy, I sometimes work until late at night.","この道はときどき込む[ことがあります]。":"This road sometimes gets congested.","休みの日は、一日中寝ている[ことがあります]。":"On my days off, I sometimes stay in bed all day."}},"～にする":{"m":"decide on, choose","how":"Noun + にする. Makes a choice among several options; often used when ordering food, shopping, or setting a time. To decide to do an action, use verb + 「ことにする」.","eg":{"私はコーヒー[にします]。":"I'll have coffee.","誕生日のプレゼントは時計[にしました]。":"I decided on a watch for the birthday present.","会議は月曜日[にしましょう]。":"Let's make the meeting Monday.","どれ[にしますか]。":"Which one will you have?"}},"～のが／～のを（名词化）":{"m":"(the act of) doing (nominalizer)","how":"Verb / adjective plain form + の + が / を. Turns a clause into a noun, as in 「～のが好きだ / 上手だ」 or 「～のを忘れる」. Note: with perception verbs such as 見る and 聞こえる, only の can be used, not こと.","eg":{"私は絵をかく[のが]好きです。":"I like drawing pictures.","姉は歌を歌う[のが]上手です。":"My older sister is good at singing.","窓を閉める[のを]忘れました。":"I forgot to close the window.","子どもたちが遊んでいる[のを]見ました。":"I saw the children playing."}},"～場合は":{"m":"in case of, if","how":"Verb plain form / い-adjective / な-adjective + な / noun + の + 場合は. Explains what to do in a certain situation; more formal than 「たら」 and common in notices, instructions, and rules.","eg":{"雨の[場合は]、試合は中止です。":"In case of rain, the game will be canceled.","遅れる[場合は]、電話で連絡してください。":"If you're going to be late, please let us know by phone.","火事の[場合は]、エレベーターを使わないでください。":"In case of fire, do not use the elevator.","わからない[場合は]、係の人に聞いてください。":"If anything is unclear, please ask a staff member."}}},"N3":{"～ようにする":{"m":"try to, make a point of (doing)","how":"Verb dictionary form / ない-form + ようにする.","eg":{}},"～ことにする":{"m":"decide to","how":"Verb dictionary form / ない-form + ことにする.","eg":{}},"～ことになる":{"m":"it has been decided that; it turns out that","how":"Verb dictionary form / ない-form + ことになる.","eg":{}},"～わけではない":{"m":"it doesn't mean that, not necessarily","how":"Plain form + わけではない; a partial negation.","eg":{}},"～わけだ":{"m":"no wonder; that means","how":"Plain form + わけだ.","eg":{}},"～はずがない":{"m":"cannot possibly","how":"Plain form + はずがない.","eg":{}},"～たばかり":{"m":"have just done","how":"Verb た-form + ばかり.","eg":{}},"～ところだ":{"m":"be about to / be in the middle of / have just done","how":"Verb dictionary form / ている form / た-form + ところだ.","eg":{}},"～によって":{"m":"depending on; by (agent); by means of","how":"Noun + によって.","eg":{}},"～について":{"m":"about, concerning","how":"Noun + について.","eg":{}},"～ために（原因）":{"m":"because of, due to","how":"Plain form / Noun + の + ために; mostly used in writing.","eg":{}},"～ように（目的）":{"m":"so that (one can)","how":"Verb potential form / ない-form, or other non-volitional expressions + ように.","eg":{}},"～らしい":{"m":"it seems that; typical of, like a true ...","how":"Plain form + らしい; Noun + らしい: like a proper (noun), typical of (noun).","eg":{}},"～ようだ／～みたいだ":{"m":"seems, looks like; like, as if","how":"Plain form + ようだ (noun + の, な-adjective + な); in speech, みたいだ is used.","eg":{}},"～っぽい":{"m":"prone to; -ish, having a feel of","how":"Noun / verb ます-stem + っぽい.","eg":{}},"～たびに":{"m":"every time, whenever","how":"Verb dictionary form / Noun + の + たびに.","eg":{}},"～おかげで":{"m":"thanks to","how":"Plain form / Noun + の + おかげで (for a good result).","eg":{}},"～せいで":{"m":"because of, it's the fault of","how":"Plain form / Noun + の + せいで (for a bad result).","eg":{}},"～ばかり":{"m":"nothing but, only; do nothing but","how":"Noun + ばかり / verb て-form + ばかりいる.","eg":{}},"～さえ～ば":{"m":"as long as, if only","how":"Noun + さえ + ...ば; verb ます-stem + さえすれば.","eg":{}},"～として":{"m":"as (in the role of)","how":"Noun + として.","eg":{}},"～に対して":{"m":"toward, to; in contrast to","how":"Noun + に対して.","eg":{}},"～にとって":{"m":"for, to (from the standpoint of)","how":"Noun + にとって.","eg":{}},"～によると":{"m":"according to","how":"Noun + によると; often paired with そうだ.","eg":{}},"～ても":{"m":"even if","how":"Verb て-form + も; い-adjective minus い + くても.","eg":{}},"～ばよかった":{"m":"should have, I wish I had","how":"Verb conditional form + ばよかった; expresses regret.","eg":{}},"～ば～ほど":{"m":"the more ..., the more ...","how":"Conditional form + ば + dictionary form + ほど.","eg":{}},"～ようとする":{"m":"be about to; try to","how":"Verb volitional form + とする.","eg":{}},"～てほしい":{"m":"want (someone) to do","how":"Verb て-form + ほしい.","eg":{}},"～ことはない":{"m":"there is no need to","how":"Verb dictionary form + ことはない.","eg":{}},"～わりに":{"m":"considering, for (unexpectedly)","how":"Plain form / Noun + の + わりに.","eg":{}},"～とおりに":{"m":"as, in the way that, according to","how":"Verb dictionary form / た-form / Noun + の + とおりに.","eg":{}},"～最中に":{"m":"in the middle of","how":"Verb ている form / Noun + の + 最中に.","eg":{}},"～うちに":{"m":"while (still); before (something changes)","how":"Verb dictionary form / ない-form / adjective / Noun + の + うちに.","eg":{}},"～きれない":{"m":"cannot finish; cannot completely","how":"Verb ます-stem + きれない.","eg":{}},"～かわりに":{"m":"instead of; in exchange for","how":"Verb dictionary form / Noun + の + かわりに.","eg":{}},"～てたまらない":{"m":"so ... one can't stand it, extremely","how":"Verb て-form / い-adjective minus い + くてたまらない.","eg":{}},"～ずに":{"m":"without doing","how":"Verb ない-form with ない removed + ずに (する becomes せずに).","eg":{}},"～だらけ":{"m":"full of, covered with","how":"Noun + だらけ (mostly negative).","eg":{}},"～ばかりでなく":{"m":"not only ... but also","how":"Noun / verb or い-adjective plain form + ばかりでなく, な-adjective + な + ばかりでなく; the second part is often paired with 「も」. Slightly more formal than 「だけでなく」.","eg":{}},"～くせに":{"m":"even though, and yet (critical)","how":"Verb / い-adjective plain form, な-adjective + な, noun + の + くせに. Carries a tone of blame or contempt; both parts have the same subject. Stronger in feeling than 「のに」, and generally not used about oneself.","eg":{}},"～っけ":{"m":"was it ...? (trying to remember)","how":"Plain form + っけ (often 「～だっけ」 or 「～たっけ」); casual speech. Used to check something you can't quite remember; can also be said to oneself.","eg":{}},"～てからでないと":{"m":"cannot ... without first ...","how":"Verb て-form + からでないと (= からでなければ); followed by a negative or an expression of difficulty.","eg":{}},"～としたら":{"m":"if, supposing (hypothetical)","how":"Plain form + としたら (= とすれば); used to suppose an uncertain or unrealistic situation, often followed by a guess, a question, or a wish.","eg":{}},"～ような気がする":{"m":"have a feeling that","how":"Verb / い-adjective plain form, な-adjective + な, noun + の + ような気がする. Expresses an uncertain, subjective feeling; softer than 「と思う」.","eg":{}},"～ふりをする":{"m":"pretend to","how":"Verb / い-adjective plain form, な-adjective + な, noun + の + ふりをする.","eg":{}},"～まま":{"m":"as is, remaining in the same state","how":"Verb た-form / ない-form, い-adjective, な-adjective + な, noun + の + まま. Means doing the second action while a certain state stays unchanged; a common mistake is attaching it to the verb dictionary form.","eg":{}},"～かけ":{"m":"half-done, in the middle of","how":"Verb ます-stem + かけ (+ の + noun) / かける. Shows that an action has started but is not finished.","eg":{}},"～っぱなし":{"m":"leave (something) as it is; keep on (doing)","how":"Verb ます-stem + っぱなし. Means leaving something as it is after doing it, or staying in the same state for a long time; often has a tone of dissatisfaction.","eg":{}},"～なんて":{"m":"things like; to think that (surprise)","how":"Noun / plain form + なんて. Expresses feelings such as contempt, unexpectedness, or surprise; casual speech.","eg":{}},"～から～にかけて":{"m":"from ... through ... (approximate range or period)","how":"Noun + から + noun + にかけて expresses an approximate range of time or space; 「から～まで」 has clearer boundaries.","eg":{}},"～たがる":{"m":"(a third person) wants to","how":"Verb ます-stem + たがる (often 「たがっている」). Used to describe other people's wishes; even though English simply says \"he wants to ...\", you cannot say 「彼は～たい」.","eg":{}},"～させられる（使役被动）":{"m":"be made to, be forced to (causative-passive)","how":"Group 1 (godan) verbs: ない-form stem + される (or せられる); Group 2 (ichidan) verbs: drop る + させられる; する becomes させられる; 来る becomes 来させられる. Expresses being made by someone else to do something unwillingly.","eg":{}},"～べきだ":{"m":"should, ought to","how":"Verb dictionary form + べきだ (する becomes するべき / すべき); the negative is 「べきではない」. Expresses what the speaker thinks is naturally the right thing to do; not used for obligations set by law.","eg":{}},"～に決まっている":{"m":"definitely, it's certain that","how":"Plain form (な-adjective stems and nouns attach directly) + に決まっている. Expresses a judgment the speaker is very sure of; casual speech.","eg":{}},"～て以来":{"m":"ever since","how":"Verb て-form + 以来 (noun + 以来); the second part is a continuing state and cannot be a one-time action.","eg":{}},"～おきに":{"m":"at intervals of, every other","how":"Quantity word + おきに. 「一日おきに」 means every other day (once every two days); for distances, it means basically the same as 「ごとに」.","eg":{}},"～こそ":{"m":"precisely, it is ... (and nothing else)","how":"Noun (or 「～からこそ」, etc.) + こそ emphasizes the preceding word, meaning \"this and nothing else\". Common in 「今度こそ」 and 「こちらこそ」.","eg":{}},"～ところに／～ところへ":{"m":"just when, at the very moment","how":"Verb dictionary form / ている form / た-form + ところに (へ). Means that at that very moment someone came or something else happened (often an interruption).","eg":{}},"～しかない":{"m":"have no choice but to","how":"Verb dictionary form + しかない. Means there is no other way, so one can only do this; be careful to distinguish it from 「～しか～ない」 (only).","eg":{}},"～ても構わない":{"m":"it's all right if","how":"Verb / い-adjective て-form, な-adjective / noun + で + も構わない. Expresses permission or concession; slightly more formal than 「てもいい」.","eg":{}},"～させてください":{"m":"please let me","how":"Verb causative て-form + ください (Group 1: ない-form stem + せてください; Group 2: drop る + させてください; する becomes させてください). Used to ask the listener for permission to do something yourself.","eg":{}},"～じゃないか":{"m":"isn't it ...?; let's","how":"Plain form (な-adjective stems and nouns attach directly) + じゃないか (polite: 「ではありませんか」). Used to remind, to reproach, or to propose (volitional form + じゃないか).","eg":{}},"～てくる／～ていく（变化）":{"m":"gradually come to (up to now) / go on (changing from now)","how":"Verb て-form + くる shows a change continuing from the past to the present (or starting to appear); + いく shows something continuing to change from now into the future.","eg":{}},"～ごとに":{"m":"every, each","how":"Noun (usually a quantity word) + ごとに. Means it is so for each time or each unit; 「一日ごとに」 means every day, which is different from 「おきに」.","eg":{}},"～とか":{"m":"things like; I heard that","how":"Noun / plain form + とか. Can be used to list examples (～とか～とか), or to express uncertain hearsay (～とか (いう)).","eg":{}},"～ということだ（传闻）":{"m":"I hear that, they say (hearsay)","how":"Plain form + ということだ (casual: 「～って」). Used to report information one has heard or read; puts more emphasis on quoting than 「そうだ」. It cannot be put in the past tense to express hearsay.","eg":{}},"～というより":{"m":"rather than (saying) ..., (it's more like)","how":"Noun / plain form (な-adjectives and nouns can attach directly) + というより, often followed by 「むしろ」. Used to rephrase something more accurately.","eg":{}},"～てはじめて":{"m":"not until (after doing), only after","how":"Verb て-form + はじめて. Means that only after experiencing something does one realize or achieve something for the first time. Don't express this \"only then / not until\" idea with 「やっと」 (finally).","eg":{}},"～てしょうがない":{"m":"terribly, unbearably","how":"Verb / い-adjective て-form, な-adjective + で + しょうがない (= しかたがない). Expresses a feeling or sensation so strong it can't be controlled; similar to 「てたまらない」 but more casual.","eg":{}}},"N2":{"～に違いない":{"m":"must be, no doubt","how":"Plain form (nouns and な-adjectives can attach directly) + に違いない.","eg":{}},"～わけにはいかない":{"m":"cannot (for moral or social reasons)","how":"Verb dictionary form + わけにはいかない.","eg":{}},"～ざるを得ない":{"m":"have no choice but to, cannot help but","how":"Verb ない-form with ない removed + ざるを得ない (する becomes せざるを得ない).","eg":{}},"～をきっかけに":{"m":"taking (something) as an opportunity","how":"Noun + をきっかけに.","eg":{}},"～に応じて":{"m":"according to, in response to","how":"Noun + に応じて.","eg":{}},"～にかかわらず":{"m":"regardless of","how":"Noun + にかかわらず.","eg":{}},"～を問わず":{"m":"regardless of, irrespective of","how":"Noun + を問わず.","eg":{}},"～ものの":{"m":"although","how":"Plain form + ものの.","eg":{}},"～一方だ":{"m":"more and more, keep (getting)","how":"Verb dictionary form + 一方だ.","eg":{}},"～に過ぎない":{"m":"nothing more than, merely","how":"Noun / plain form + に過ぎない.","eg":{}},"～かねない":{"m":"could well (lead to a bad result)","how":"Verb ます-stem + かねない.","eg":{}},"～かねる":{"m":"find it difficult to, cannot","how":"Verb ます-stem + かねる (a polite refusal).","eg":{}},"～どころか":{"m":"far from; on the contrary","how":"Plain form + どころか.","eg":{}},"～に際して":{"m":"on the occasion of","how":"Noun / verb dictionary form + に際して.","eg":{}},"～にあたって":{"m":"at the time of (an important occasion)","how":"Noun / verb dictionary form + にあたって.","eg":{}},"～に沿って":{"m":"along; in line with","how":"Noun + に沿って.","eg":{}},"～をもとに":{"m":"based on","how":"Noun + をもとに (して).","eg":{}},"～を中心に":{"m":"centered on","how":"Noun + を中心に (して).","eg":{}},"～を通じて":{"m":"through; throughout (a period)","how":"Noun + を通じて.","eg":{}},"～にわたって":{"m":"over, throughout (a range); for as long as","how":"Noun + にわたって.","eg":{}},"～上で":{"m":"after (doing); in terms of","how":"Verb た-form / Noun + の + 上で; verb dictionary form + 上で: in terms of, when it comes to.","eg":{}},"～からこそ":{"m":"precisely because","how":"Plain form + からこそ.","eg":{}},"～からには":{"m":"since, now that","how":"Plain form + からには.","eg":{}},"～以上は":{"m":"since, now that","how":"Plain form + 以上 (は).","eg":{}},"～ことから":{"m":"because, from the fact that","how":"Plain form + ことから; explains the reason for a name or a judgment.","eg":{}},"～ことだ":{"m":"should, it's best to","how":"Verb dictionary form / ない-form + ことだ (advice).","eg":{}},"～ものだ":{"m":"it's natural that; how ... (exclamation)","how":"Verb dictionary form + ものだ; た-form + ものだ: reminiscing (used to).","eg":{}},"～ようがない":{"m":"there is no way to","how":"Verb ます-stem + ようがない.","eg":{}},"～つつある":{"m":"be in the process of (gradual change)","how":"Verb ます-stem + つつある.","eg":{}},"～ばかりか":{"m":"not only ... but also","how":"Plain form + ばかりか.","eg":{}},"～に限らず":{"m":"not limited to","how":"Noun + に限らず.","eg":{}},"～に反して":{"m":"contrary to","how":"Noun + に反して.","eg":{}},"～わりには":{"m":"out of proportion to; unexpectedly, considering","how":"Plain form / Noun + の + わりには.","eg":{}},"～に先立って":{"m":"prior to, before","how":"Noun / verb dictionary form + に先立って.","eg":{}},"～てならない":{"m":"extremely, can't help feeling","how":"Verb て-form / い-adjective minus い + くてならない.","eg":{}},"～に関して":{"m":"regarding, concerning","how":"Noun + に関して / Noun + に関する + noun. More formal than 「について」 and mostly used in writing, meetings, and reports; to modify a noun, use 「に関する」 (you cannot put 「に関して」 directly before a noun).","eg":{}},"～にしたがって":{"m":"as; in accordance with","how":"Noun / verb dictionary form + にしたがって. (1) Shows that as one thing changes, another changes along with it; (2) after a noun, it can also mean following instructions or rules (in this case it cannot be replaced with 「につれて」). Note that the second part is a natural change, not a one-time action.","eg":{}},"～につれて":{"m":"as (one thing changes, so does another)","how":"Noun / verb dictionary form + につれて. Shows that a change in the first part brings about a gradual change in the second; both parts must be changes. It cannot mean \"following instructions\", which is how it differs from 「にしたがって」.","eg":{}},"～に伴って":{"m":"along with, as","how":"Noun / verb dictionary form + に伴って (to modify a noun, 「に伴う」). More formal than 「につれて」 and often used for social changes and in news reports; it can also express a result brought about by a one-time change.","eg":{}},"～とともに":{"m":"together with; as; at the same time as","how":"Noun / verb dictionary form + とともに. (1) \"together with\" (more formal than 「と一緒に」); (2) \"as (one changes, so does the other)\"; (3) \"at the same time as\". Strongly written in tone.","eg":{}},"～に比べて":{"m":"compared with","how":"Noun + に比べて / に比べると. Used to compare two things; the second part expresses a difference in degree. Learners often leave out the 「に」 and say 「を比べて」, so be careful.","eg":{}},"～に加えて":{"m":"in addition to","how":"Noun + に加えて. Adds something of the same kind to what is already there; the second part often uses 「も」. More formal than 「だけでなく」.","eg":{}},"～をはじめ":{"m":"starting with, led by; as well as","how":"Noun + をはじめ (として). First names one representative example, then covers other things of the same kind; the second part often contains 「など」, 「多くの」, or 「いろいろな」.","eg":{}},"～はもちろん":{"m":"not to mention ..., also","how":"Noun + はもちろん (のこと). The first item is taken for granted, and the second part emphasizes that other things are included too; the second part often uses 「も」 or 「まで」.","eg":{}},"～はともかく":{"m":"setting aside, leaving ... aside","how":"Noun + はともかく (として). Puts the first item aside for now and gives priority to the second. Note that this is the opposite of 「はもちろん」: the first item is temporarily set aside rather than taken for granted.","eg":{}},"～をめぐって":{"m":"over, surrounding (an issue)","how":"Noun + をめぐって (to modify a noun, 「をめぐる」). Expresses that debate, conflict, discussion, etc. arise around an issue; the second part usually has words like 「議論」, 「対立」, or 「争う」.","eg":{}},"～において":{"m":"in, at (a place, time, or field)","how":"Noun + において (to modify a noun, 「における」). A written equivalent of 「で」, used in formal situations and in writing. In everyday conversation 「で」 sounds natural, while 「において」 sounds stiff.","eg":{}},"～にかけては":{"m":"when it comes to (being the best at)","how":"Noun + にかけては. Expresses outstanding ability in some area, second to none; the second part is usually a positive evaluation. Not used for negative evaluations or simply to introduce a topic.","eg":{}},"～向け":{"m":"intended for, aimed at","how":"Noun + 向け (だ / の / に). Means made or designed specifically for a certain target. Note the difference from 「向き」: 「向け」 means deliberately made for a target, while 「向き」 means naturally suited to it.","eg":{}},"～を込めて":{"m":"filled with, putting (feeling) into","how":"Noun + を込めて (to modify a noun, 「を込めた」). Usually follows nouns for feelings such as 「心」, 「愛」, 「感謝」, or 「願い」, meaning doing something while pouring that feeling into it.","eg":{}},"～次第":{"m":"as soon as","how":"Verb ます-stem / noun (expressing an action) + 次第. Means that as soon as the first part happens, the second will be done right away; the second part is usually the speaker's intention or a request and cannot be a past fact, so you cannot say 「着き次第電話した」.","eg":{}},"～たとたん":{"m":"the moment, just as (something unexpected happens)","how":"Verb た-form + とたん (に). Means that the second event happens right after the first, and it is usually something the speaker did not expect. The second part cannot be in a volitional or imperative form.","eg":{}},"～かと思うと":{"m":"no sooner ... than; just when I thought ..., (but)","how":"Verb た-form + かと思うと / かと思ったら. Describes successive changes in other people or things, with a sense of surprise; it cannot be used for the speaker's own actions.","eg":{}},"～ついでに":{"m":"while (one is at it), on the occasion of","how":"Noun + の / verb dictionary form or た-form + ついでに. Means doing something else on the side while doing the main thing; the first part is the main purpose and the second is incidental.","eg":{}},"～うえに":{"m":"not only ... but also, on top of","how":"Plain form (な-adjective + な / である, noun + の / である) + うえに. Adds things in the same direction (good on top of good, bad on top of bad); both parts must have the same kind of evaluation.","eg":{}},"～反面":{"m":"on the other hand, while","how":"Plain form (な-adjective + な / である, noun + である) + 反面. Shows that the same thing has two opposite sides; the two parts have opposite evaluations.","eg":{}},"～にしては":{"m":"for (a ...), surprisingly","how":"Plain form (nouns and な-adjective stems attach directly) + にしては. Means that judged by the standard of the first part, the second part is unexpected. Close to 「わりには」, but with 「にしては」 the first part is usually a specific fact.","eg":{}},"～にしても":{"m":"even if; even though","how":"Plain form (nouns and な-adjective stems can attach directly) + にしても. Means that even if the first part is accepted, the second part does not change; often has a tone of dissatisfaction, criticism, or concession.","eg":{}},"～だけあって":{"m":"as might be expected of; precisely because (naturally)","how":"Plain form (nouns and な-adjective stems attach directly) + だけあって. Expresses a good result that matches the first part (status, effort, etc.); usually a positive evaluation that shows admiration.","eg":{}},"～だけに":{"m":"all the more because","how":"Plain form (nouns and な-adjective stems attach directly) + だけに. Because of the special circumstances in the first part, the second part is all the greater in degree; the second part can be good or bad (often used as in \"all the more disappointing because expectations were high\").","eg":{}},"～ばかりに":{"m":"just because (leading to a bad result)","how":"Plain form (な-adjective + な / である, noun + である) + ばかりに. Means that just one cause led to a bad result, with a tone of regret; the second part is generally negative.","eg":{}},"～あげく":{"m":"after (much ...), in the end","how":"Verb た-form / Noun + の + あげく (に). Means that after a long period of trouble or going back and forth, the end result is bad or has to be accepted.","eg":{}},"～末に":{"m":"after (a long process), finally","how":"Verb た-form / Noun + の + 末 (に). Means that a result is reached after a process of effort, thought, etc.; the result can be good or bad. More neutral and more written than 「あげく」.","eg":{}},"～ものだから":{"m":"because (giving an excuse)","how":"Plain form (な-adjective + な, noun + な) + ものだから. In speech it is often 「もんだから」. Used to explain personal reasons or to make excuses, with a nuance of \"it couldn't be helped\"; the second part cannot be a command or a request.","eg":{}},"～ものなら":{"m":"if one could; if one were to (with serious consequences)","how":"(1) Potential verb dictionary form + ものなら: a wish that is hard to realize; (2) volitional form + ものなら: once you do it, there will be serious consequences.","eg":{}},"～とは限らない":{"m":"not necessarily","how":"Plain form + とは限らない (often with 「必ずしも」, 「いつも」, or 「誰でも」). Expresses partial negation; do not read it as a total negation (\"is not\").","eg":{}},"～わけがない":{"m":"there's no way that, cannot possibly","how":"Plain form (な-adjective + な, noun + な / である) + わけがない. The speaker strongly denies a possibility based on reasons; more subjective and stronger than 「はずがない」.","eg":{}},"～っこない":{"m":"there's no way (casual)","how":"Verb ます-stem + っこない. A casual expression mostly used among friends; not used in formal situations or in writing.","eg":{}},"～ないことはない":{"m":"it's not that (one) can't / doesn't","how":"Verb ない-form / い-adjective minus い + くない / な-adjective or noun + でない + ことはない. A double negative expressing a reluctant affirmative: it is possible, but without much enthusiasm or only under certain conditions.","eg":{}},"～ないことには":{"m":"unless ..., (cannot)","how":"Verb ない-form + ことには (followed by a negative). Means the first part is a necessary condition: unless it is realized, the second part cannot happen; the second part must be negative or unfavorable.","eg":{}},"～おそれがある":{"m":"there is a risk that, might (something bad)","how":"Verb dictionary form / Noun + の + おそれがある. Expresses the possibility that something bad will happen; mostly used in formal contexts such as the news and weather forecasts, and only for bad things.","eg":{}},"～がちだ":{"m":"tend to, be apt to","how":"Verb ます-stem / noun + がちだ (to modify a noun, 「がちな」). Expresses a tendency for something (usually undesirable) to happen, though not necessarily often. Note: not used for positive tendencies.","eg":{}},"～気味":{"m":"slightly, a touch of","how":"Verb ます-stem / noun + 気味 (だ / の). Expresses a slight tendency or symptom (usually undesirable); the degree is mild. Read as 「ぎみ」.","eg":{}},"～ことなく":{"m":"without (doing)","how":"Verb dictionary form + ことなく. A written expression equivalent to 「ないで」 or 「ずに」, meaning doing the second action without doing the first; often implies \"not even once\".","eg":{}},"～にほかならない":{"m":"nothing other than, none other than","how":"Noun / plain form + にほかならない (when giving a reason, 「からにほかならない」 is common). Asserts \"it is nothing else but ...\"; written and strong in tone.","eg":{}}},"N1":{"～をもって":{"m":"with, by means of; as of (a point in time)","how":"Noun + をもって.","eg":{}},"～ずにはいられない":{"m":"cannot help (doing)","how":"Verb ない-form with ない removed + ずにはいられない (する becomes せずには).","eg":{}},"～てやまない":{"m":"sincerely; never cease to","how":"Verb て-form + やまない.","eg":{}},"～といえども":{"m":"even though, even if","how":"Noun / plain form + といえども.","eg":{}},"～ならでは":{"m":"unique to, only ... could","how":"Noun + ならではの.","eg":{}},"～を余儀なくされる":{"m":"be forced to, have no choice but to","how":"Noun + を余儀なくされる.","eg":{}},"～まじき":{"m":"unbecoming of, that should not be (done)","how":"Verb dictionary form + まじき + noun (する becomes すまじき).","eg":{}},"～に至っては":{"m":"as for (an extreme example)","how":"Noun + に至っては.","eg":{}},"～ともなると":{"m":"once it comes to (being), when it reaches the level of","how":"Noun + ともなると.","eg":{}},"～が早いか":{"m":"no sooner ... than","how":"Verb dictionary form / た-form + が早いか.","eg":{}},"～や否や":{"m":"as soon as","how":"Verb dictionary form + や否や.","eg":{}},"～きらいがある":{"m":"have a (bad) tendency to","how":"Verb dictionary form / Noun + の + きらいがある.","eg":{}},"～に足る":{"m":"worthy of, sufficient to","how":"Verb dictionary form / noun + に足る.","eg":{}},"～に堪えない":{"m":"cannot bear to; deeply (feel)","how":"Verb dictionary form / noun + に堪えない.","eg":{}},"～ながらも":{"m":"although","how":"Verb ます-stem / adjective / noun + ながらも.","eg":{}},"～をよそに":{"m":"in disregard of, ignoring","how":"Noun + をよそに.","eg":{}},"～にもまして":{"m":"even more than","how":"Noun + にもまして.","eg":{}},"～たりとも":{"m":"not even (a single ...)","how":"Quantity word with 「一」 (one) + たりとも + negative.","eg":{}},"～をおいて":{"m":"other than (there is no one / nothing else)","how":"Noun + をおいて + negative.","eg":{}},"～ずくめ":{"m":"nothing but, entirely","how":"Noun + ずくめ.","eg":{}},"～極まりない":{"m":"extremely","how":"な-adjective stem + 極まりない.","eg":{}},"～を皮切りに":{"m":"starting with","how":"Noun + を皮切りに (して).","eg":{}},"～とあって":{"m":"because (of special circumstances)","how":"Plain form / noun + とあって.","eg":{}},"～ものを":{"m":"if only ..., but (regret)","how":"Plain form + ものを.","eg":{}},"～とは":{"m":"to think that (surprise)","how":"Plain form + とは.","eg":{}},"～てからというもの":{"m":"ever since (continuously)","how":"Verb て-form + からというもの.","eg":{}},"～べく":{"m":"in order to","how":"Verb dictionary form + べく (する becomes すべく).","eg":{}},"～んがため":{"m":"in order to","how":"Verb ない-form with ない removed + んがため (する becomes せんがため).","eg":{}},"～に即して":{"m":"in accordance with, based on","how":"Noun + に即して.","eg":{}},"～かたがた":{"m":"while (one is at it), combined with","how":"Noun + かたがた.","eg":{}},"～がてら":{"m":"while, at the same time as (on the way)","how":"Noun / verb ます-stem + がてら.","eg":{}},"～までもない":{"m":"there's no need to","how":"Verb dictionary form + までもない.","eg":{}},"～をものともせずに":{"m":"undaunted by, in defiance of","how":"Noun + をものともせずに.","eg":{}},"～なり":{"m":"as soon as (immediately)","how":"Verb dictionary form + なり. Both parts have the same subject, and it is generally not used about the speaker; the second part is usually an unexpected action and cannot be a command or a statement of intention.","eg":{}},"～そばから":{"m":"no sooner ... than (again)","how":"Verb dictionary form / た-form + そばから. Used for things that happen repeatedly, with a tone of helplessness or dissatisfaction; not used for something that happens only once.","eg":{}},"～が最後":{"m":"once ... (inevitably leading to a bad result)","how":"Verb た-form + が最後. The second part is usually an irreversible negative result; in speech, 「たら最後」 is also used.","eg":{}},"～はおろか":{"m":"let alone, not to mention","how":"Noun + はおろか, often followed by 「も」, 「さえ」, or 「すら」 + negative. The first item is the milder one and the second is more extreme; cannot be used in commands or invitations.","eg":{}},"～もさることながら":{"m":"not only ..., but even more so","how":"Noun + もさることながら. Affirms the first item while emphasizing that the second is even more important; mostly used for positive evaluations.","eg":{}},"～すら":{"m":"even","how":"Noun (+ particle) + すら. Similar in meaning to 「さえ」 but more written; mostly used with negative or unfavorable content.","eg":{}},"～なりとも":{"m":"even just (a little)","how":"Noun (usually a word for a small amount) + なりとも. Expresses a minimal wish; often used with 「少し」, 「一目」, 「多少」, etc.","eg":{}},"～とあれば":{"m":"if it's (for) ..., (one is willing to)","how":"Noun / plain form + とあれば. The first part is a special situation or an important reason, and the second part says one is willing to do something for it.","eg":{}},"～ならいざしらず":{"m":"it might be understandable if ..., but","how":"Noun / plain form + ならいざしらず. The first part is a special, understandable case; the second part points out that the current situation is unacceptable. Note: although it contains 知らず, it does not mean \"not know\" here.","eg":{}},"～ないまでも":{"m":"even if not ..., at least","how":"Verb ない-form + までも. The first part is a higher degree, and the second is the minimum requirement; often used with 「せめて」 or 「少なくとも」.","eg":{}},"～なしに":{"m":"without; without ..., (cannot)","how":"Noun / verb dictionary form + こと + なしに (は). 「～なしには～ない」 means \"cannot ... without ...\".","eg":{}},"～をもってすれば":{"m":"with (something), (one could)","how":"Noun + をもってすれば. The first part is usually a powerful means such as ability or skill, and the second part is a positive possible result.","eg":{}},"～いかんで":{"m":"depending on","how":"Noun (+ の) + いかんで / いかんによって (は). Written language; means the result changes depending on the first part.","eg":{}},"～いかんにかかわらず":{"m":"regardless of (how)","how":"Noun (+ の) + いかんにかかわらず / いかんによらず. Written language; more formal than 「にかかわらず」.","eg":{}},"～にひきかえ":{"m":"in contrast to, compared with","how":"Noun / plain form + の + にひきかえ. Contrasts two opposite things, often with the speaker's subjective evaluation (dissatisfaction, etc.).","eg":{}},"～と相まって":{"m":"combined with, coupled with","how":"Noun + と相まって. Two factors interact to produce a stronger effect.","eg":{}},"～に先駆けて":{"m":"ahead of, leading the way","how":"Noun + に先駆けて. Doing something earlier than other people or things; mostly used for positive, pioneering things.","eg":{}},"～を限りに":{"m":"with ... as the last; no longer after","how":"Noun (time) + を限りに. Means that something that has continued comes to an end as of a certain time.","eg":{}},"～を踏まえて":{"m":"based on, taking into account","how":"Noun + を踏まえて. Uses facts, opinions, etc. as the basis for a judgment or action; mostly used in formal settings.","eg":{}},"～に則って":{"m":"in accordance with","how":"Noun + に則って. The first part is usually a norm such as a rule, law, or tradition; more formal than 「に沿って」.","eg":{}},"～にかかわる":{"m":"affecting, involving","how":"Noun + にかかわる. Usually follows important things such as 「命」, 「名誉」, 「将来」, or 「評判」, and means having a major effect on them.","eg":{}},"～んばかりに":{"m":"as if about to","how":"Verb ない-form with ない removed + んばかりに (する becomes せんばかりに). Means that although it does not actually happen, it looks almost as if it will; mostly used to describe other people's appearance.","eg":{}},"～とばかりに":{"m":"as if to say","how":"Plain form (often imperative or volitional) + とばかりに. Although not said out loud, it is clearly shown in one's attitude; not used about the speaker.","eg":{}},"～ともなく":{"m":"without meaning to, idly","how":"Verb dictionary form + ともなく (often 「見る」, 「聞く」, or 「言う」). Can also follow a question word + particle, as in 「どこからともなく」.","eg":{}},"～ながらに":{"m":"while, in the state of","how":"Noun / verb ます-stem + ながらに. Mostly used in set phrases such as 「涙ながらに」, 「生まれながらに」, 「昔ながらの」, and 「居ながらにして」.","eg":{}},"～ずじまい":{"m":"end up never (doing)","how":"Verb ない-form with ない removed + ずじまい (する becomes せずじまい). Means that something one wanted to do was never done in the end, with a sense of regret.","eg":{}},"～までだ":{"m":"(if it comes to that) will just ...; merely","how":"Verb dictionary form + までだ (expresses resolve: if nothing else works, one will just do it); verb た-form + までだ (means one merely did it, with no other intention).","eg":{}},"～ばそれまでだ":{"m":"if ..., that's the end of it","how":"Verb ば-form + それまでだ. Means that once something happens, everything will have been in vain.","eg":{}},"～始末だ":{"m":"end up (in a bad state), in the end even","how":"Verb dictionary form / Noun + の + 始末だ. Means that after a series of bad things, an even worse result finally occurs; carries a tone of criticism or resignation.","eg":{}},"～限りだ":{"m":"extremely, utterly","how":"い-adjective dictionary form / な-adjective + な + 限りだ. Expresses the speaker's own strong feelings; not used to describe other people's feelings.","eg":{}},"～には及ばない":{"m":"there is no need to","how":"Verb dictionary form / noun + には及ばない. Mostly used to tell someone politely \"please don't trouble yourself\".","eg":{}},"～てしかるべきだ":{"m":"should naturally, ought to","how":"Verb て-form + しかるべきだ. Means that by reason it is only natural that things should be so; written language.","eg":{}},"～ではあるまいし":{"m":"it's not as if ..., (so)","how":"Noun / verb dictionary form + の + ではあるまいし. The second part is usually advice, criticism, or a command; in speech, 「じゃあるまいし」 is common.","eg":{}},"～と思いきや":{"m":"I thought ..., but (unexpectedly)","how":"Plain form + と思いきや. Means the result was the opposite of what was expected, with a sense of surprise; the second part is something that has already happened.","eg":{}},"～とはいえ":{"m":"although, even so","how":"Plain form / noun + とはいえ. Acknowledges the first part as a fact, while the second part points out something that does not match it. Note: different from 「とは」, which expresses surprise.","eg":{}},"～にかこつけて":{"m":"using ... as an excuse","how":"Noun + にかこつけて. Using something as a pretext to do something else; carries a tone of criticism.","eg":{}},"～にしたところで":{"m":"even for, even if (one is)","how":"Noun + にしたところで. Means it is the same even from a certain standpoint; usually followed by negative or unfavorable content.","eg":{}},"～であれ～であれ":{"m":"whether ... or ...","how":"Noun + であれ + noun + であれ. Lists examples, meaning it is the same in either case.","eg":{}},"～たところで":{"m":"even if (it's no use)","how":"Verb た-form + ところで. The second part is a negative or unfavorable judgment, meaning that doing it would be futile; often used with 「いくら」 or 「どんなに」.","eg":{}},"～ないものでもない":{"m":"it's not that (one) won't / can't","how":"Verb ない-form + ものでもない. Says reluctantly, under certain conditions, that something is possible; indirect in tone.","eg":{}},"～めく":{"m":"have a hint of, seem like","how":"Noun + めく (a Group 1 (godan) verb; often used as 「めいた」). Examples: 「春めく」, 「冗談めく」, 「皮肉めく」.","eg":{}},"～てはばからない":{"m":"not hesitate to, openly","how":"Verb て-form + はばからない. Means saying or doing something without any reserve; often carries a critical tone.","eg":{}}}};
